import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-04-13 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-04-13 :: Ceph Orchestration Meeting","date":"2020-04-13T00:00:00.000Z","updated":"2020-04-14T00:00:00.000Z","tags":["Ceph","分布式存储","高可用性","自动化测试","灾难恢复","Rook","Def ADM"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-13_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-04-13_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2020/2020-04-13_-_-_Ceph_Orchestration_Meeting.md"};function o(n,e,s,h,_,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li><strong>日期：</strong> 2020年4月13日</li><li><strong>参与人员：</strong> Sebastian、Travis、Jeff、Daniel、Danny等（由于假期，部分人员未出席）</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>系统故障转移与恢复讨论</strong></p><ul><li>讨论了Ceph系统的故障转移和恢复机制，特别是Ceph管理器（Manager）的恢复能力和健康状态。</li><li>提到了Def ADM模块的测试不足问题，建议增加测试以确保在灾难恢复情况下的有效性。</li></ul></li><li><p><strong>管理器（Manager）与组件的高可用性</strong></p><ul><li>探讨了在管理器节点上部署多个组件（如Prometheus、Grafana等）的必要性和方式。</li><li>讨论了使用HAProxy进行负载均衡和故障转移的可能性，以及如何确保服务在管理器故障时的连续性。</li></ul></li><li><p><strong>Rook与Def ADM的集成与测试</strong></p><ul><li>讨论了Rook与Def ADM的集成测试进展，特别是关于夜间自动化测试的实施，以尽早发现问题。</li><li>提到了当前测试中存在的问题，如CIA测试失败，并讨论了解决方案和后续步骤。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步测试和验证管理器的高可用性和故障转移机制，特别是在使用HAProxy的情况下。</li><li>计划在下一个会议中深入讨论管理器和组件的高可用性配置，并与上游团队协调。</li><li>确认将实施夜间自动化测试，以持续监控Rook与Def ADM的集成稳定性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>增加对Def ADM模块的测试，特别是在灾难恢复场景下的测试。</li><li>研究并实施HAProxy配置，以支持管理器的高可用性和故障转移。</li><li>继续推进Rook与Def ADM的集成测试，确保所有组件的稳定性和兼容性。</li><li>跟踪并解决当前测试中遇到的问题，如CIA测试失败，并确保相关修复尽快合并到主分支。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Rook 1.3版本的发布情况，确认目前没有其他紧急的Orchestration问题需要讨论。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，计划在后续会议中继续讨论未决问题。</li></ul><p><strong>备注：</strong> 原始字幕内容中存在一些不清晰的部分和重复内容，上述纪要可能需要根据实际会议内容进行调整和补充。</p>',14)])])}const p=a(r,[["render",o]]);export{c as __pageData,p as default};
